// Every screen has a real background image — this wraps any page
const PageBg = ({src, overlay="rgba(4,12,6,.82)", children, style={}}) => (
  <div style={{position:"relative",overflow:"hidden",...style}}>
    <div style={{position:"absolute",inset:0,zIndex:0,
      backgroundImage:`url(${src})`,backgroundSize:"cover",backgroundPosition:"center",
      animation:"bgKen 20s ease-in-out infinite alternate",filter:"brightness(.88)"}}/>
    <div style={{position:"absolute",inset:0,zIndex:1,background:overlay}}/>
    <div style={{position:"relative",zIndex:2}}>{children}</div>
  </div>
);

// Frosted glass panel — sits on top of backgrounds
