// Notification slides in from LEFT
const NotifBanner = ({notif,dismiss}) => {
  const [out,setOut]=useState(false);
  useEffect(()=>{
    if(!notif)return;
    setOut(false);
    const t=setTimeout(()=>{setOut(true);setTimeout(dismiss,450);},5000);
    return()=>clearTimeout(t);
  },[notif]);
  if(!notif)return null;
  return (
    <div style={{position:"fixed",top:14,left:12,right:12,zIndex:9999,maxWidth:420,margin:"0 auto",
      animation:out?"exitLeft .45s forwards":"slideLeft .5s cubic-bezier(.22,1.6,.5,1) forwards"}}>
      <div style={{background:"rgba(8,18,10,.97)",backdropFilter:"blur(24px)",borderRadius:16,
        padding:"12px 16px",border:"1px solid rgba(255,255,255,.1)",
        boxShadow:"0 16px 48px rgba(0,0,0,.5)",display:"flex",gap:12,alignItems:"center"}}>
        <div style={{fontSize:26,flexShrink:0}}>{notif.icon||"🔔"}</div>
        <div style={{flex:1}}>
          <div style={{color:"#fff",fontWeight:700,fontSize:13,lineHeight:1.3}}>{notif.title}</div>
          <div style={{color:"rgba(255,255,255,.55)",fontSize:11,marginTop:2}}>{notif.body}</div>
        </div>
        <button onClick={()=>{setOut(true);setTimeout(dismiss,450);}}
          style={{background:"none",border:"none",color:"rgba(255,255,255,.4)",fontSize:18,cursor:"pointer"}}>✕</button>
      </div>
    </div>
  );
};

// Escrow modal — uses uploaded NFC image as header bg
const EscrowModal = ({item,role,onClose}) => {
  const [step,setStep]=useState(0);
  const [loading,setLoading]=useState(false);
  const R=ROLES[role]||ROLES.buyer;
  const advance=()=>{setLoading(true);setTimeout(()=>{setLoading(false);setStep(s=>s+1);},1000);};
  const total=item?(+((item.price||1.2)*(item.qty||5)+1.80+(item.price||1.2)*(item.qty||5)*.03).toFixed(2)):7.98;
  const steps=["Review","Payment","Secured","Dispatched","Confirm","Released"];
  return (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.8)",zIndex:800,display:"flex",alignItems:"flex-end",backdropFilter:"blur(8px)"}}>
      <div style={{background:"#fff",width:"100%",maxWidth:480,margin:"0 auto",borderRadius:"28px 28px 0 0",maxHeight:"90vh",overflowY:"auto",animation:"slideUp .35s ease"}}>
        <PageBg src={IMG_NFC} overlay="rgba(4,12,8,.85)" style={{height:76,flexShrink:0,borderRadius:"28px 28px 0 0"}}>
          <div style={{padding:"16px 20px",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
            <div style={{fontFamily:"'Fraunces',serif",fontSize:18,fontWeight:700,color:"#fff"}}>Secure Escrow Checkout</div>
            <button onClick={onClose} style={{background:"rgba(255,255,255,.15)",border:"1px solid rgba(255,255,255,.25)",width:32,height:32,borderRadius:16,cursor:"pointer",fontSize:16,color:"#fff"}}>✕</button>
          </div>
        </PageBg>
        <div style={{padding:20}}>
          <div style={{display:"flex",gap:4,marginBottom:20}}>
            {steps.map((s,i)=>(
              <div key={i} style={{flex:1,textAlign:"center"}}>
                <div style={{width:24,height:24,borderRadius:12,
                  background:i<step?R.accent:i===step?"#0F172A":"#E5E7EB",
                  color:"#fff",fontSize:10,fontWeight:700,display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 3px"}}>
                  {i<step?"✓":i+1}
                </div>
                <div style={{fontSize:8,color:i===step?"#0F172A":"#9CA3AF",fontWeight:i===step?700:400}}>{s}</div>
              </div>
            ))}
          </div>
          {step===0&&<>
            <div style={{background:"#F8FAFC",borderRadius:14,padding:14,marginBottom:14}}>
              <div style={{fontWeight:700,fontSize:15,marginBottom:8}}>{item?.product||"Order"} × {item?.qty||5} {item?.unit||"kg"}</div>
              {[["Subtotal",money((item?.price||1.2)*(item?.qty||5))],["Fee (3%)",money((item?.price||1.2)*(item?.qty||5)*.03)],["Delivery","$1.80"],["TOTAL",money(total)]].map(([l,v],i)=>(
                <div key={l} style={{display:"flex",justifyContent:"space-between",padding:"4px 0",fontSize:13,
                  fontWeight:i===3?800:400,borderTop:i===3?"1px solid #E5E7EB":"none",marginTop:i===3?6:0}}>
                  <span style={{color:i===3?"#0F172A":"#6B7280"}}>{l}</span>
                  <span style={{color:i===3?R.accent:"#374151"}}>{v}</span>
                </div>
              ))}
            </div>
            <div style={{background:"#ECFDF5",borderRadius:10,padding:"10px 14px",marginBottom:14,fontSize:12,color:"#065F46",border:"1px solid #A7F3D0"}}>🔒 Payment held in escrow until you confirm delivery</div>
            <button onClick={advance} disabled={loading} style={{width:"100%",padding:15,borderRadius:14,background:R.grad,color:"#fff",fontWeight:800,fontSize:15,border:"none",cursor:"pointer"}}>{loading?"…":"PROCEED TO PAYMENT →"}</button>
          </>}
          {step===1&&<>
            <div style={{fontWeight:700,marginBottom:12}}>Choose payment method</div>
            {[{i:"📱",n:"EcoCash",d:"Instant · No fees"},{i:"💳",n:"InnBucks",d:"Linked account"},{i:"🏦",n:"OneMoney",d:"Bank transfer"}].map(m=>(
              <div key={m.n} onClick={advance} style={{padding:14,borderRadius:14,border:"1.5px solid #E5E7EB",marginBottom:10,cursor:"pointer",display:"flex",gap:12,alignItems:"center"}}>
                <span style={{fontSize:26}}>{m.i}</span>
                <div style={{flex:1}}><div style={{fontWeight:700}}>{m.n}</div><div style={{fontSize:12,color:"#6B7280"}}>{m.d}</div></div>
                <div style={{fontWeight:800,color:R.accent}}>{money(total)}</div>
              </div>
            ))}
            {loading&&<div style={{textAlign:"center",color:R.accent,fontWeight:700,padding:12}}>⏳ Processing…</div>}
          </>}
          {step===2&&<div style={{textAlign:"center",padding:"24px 0"}}>
            <div style={{fontSize:54,animation:"pulse 2s infinite",marginBottom:12}}>🔒</div>
            <div style={{fontFamily:"'Fraunces',serif",fontSize:22,fontWeight:700,color:"#065F46",marginBottom:8}}>Payment Secured</div>
            <div style={{fontSize:13,color:"#6B7280",marginBottom:20}}>{money(total)} safely held. Releases on delivery confirmation.</div>
            <div style={{background:"#F0FDF4",borderRadius:14,padding:12,marginBottom:20,border:"1px solid #D1FAE5"}}>
              <div style={{fontSize:11,color:"#9CA3AF"}}>ESCROW REF</div>
              <div style={{fontWeight:900,fontSize:18,color:"#065F46"}}>ESC-{uid()}</div>
            </div>
            <button onClick={advance} disabled={loading} style={{width:"100%",padding:14,borderRadius:14,background:R.grad,color:"#fff",fontWeight:800,border:"none",cursor:"pointer"}}>{loading?"Notifying…":"ASSIGN RIDER →"}</button>
          </div>}
          {step===3&&<div style={{textAlign:"center",padding:"24px 0"}}>
            <div style={{fontSize:54,marginBottom:12}}>🛵</div>
            <div style={{fontFamily:"'Fraunces',serif",fontSize:22,fontWeight:700,marginBottom:8}}>Rider Dispatched!</div>
            <div style={{fontSize:13,color:"#6B7280",marginBottom:16}}>ETA: ~18 minutes · Live tracking active</div>
            <div style={{background:"#FEF3C7",borderRadius:14,padding:12,marginBottom:16,fontSize:12,color:"#92400E",border:"1px solid #FCD34D"}}>⚠ Only release payment after physically receiving goods.</div>
            <button onClick={advance} disabled={loading} style={{width:"100%",padding:14,borderRadius:14,background:R.grad,color:"#fff",fontWeight:800,border:"none",cursor:"pointer"}}>{loading?"…":"I RECEIVED MY ORDER ✓"}</button>
          </div>}
          {step===4&&<div style={{textAlign:"center",padding:"24px 0"}}>
            <div style={{fontSize:54,marginBottom:12}}>📍</div>
            <div style={{fontFamily:"'Fraunces',serif",fontSize:22,fontWeight:700,marginBottom:8}}>Confirm Delivery</div>
            <div style={{fontSize:13,color:"#6B7280",marginBottom:20}}>Confirming releases {money(total)} to the seller.</div>
            <div style={{display:"flex",gap:10}}>
              <button style={{flex:1,padding:13,borderRadius:14,background:"#FEE2E2",color:"#991B1B",border:"1px solid #FECACA",fontWeight:700,cursor:"pointer"}}>⚠ Dispute</button>
              <button onClick={advance} disabled={loading} style={{flex:2,padding:13,borderRadius:14,background:R.grad,color:"#fff",fontWeight:800,border:"none",cursor:"pointer"}}>{loading?"Releasing…":"✅ CONFIRM & RELEASE"}</button>
            </div>
          </div>}
          {step===5&&<div style={{textAlign:"center",padding:"24px 0"}}>
            <div style={{fontSize:54,marginBottom:12}}>💰</div>
            <div style={{fontFamily:"'Fraunces',serif",fontSize:24,fontWeight:700,color:"#065F46",marginBottom:8}}>Payment Released!</div>
            <div style={{fontSize:14,color:"#6B7280",marginBottom:20}}>Transaction complete. Funds sent to seller.</div>
            <button onClick={onClose} style={{width:"100%",padding:14,borderRadius:14,background:R.grad,color:"#fff",fontWeight:800,border:"none",cursor:"pointer"}}>DONE</button>
          </div>}
        </div>
      </div>
    </div>
  );
};


// ── SPLASH ────────────────────────────────────────────────────────────
const Splash = ({onDone}) => {
  const [ph,setPh]=useState(0);
  useEffect(()=>{ [300,1000,1800,3200].forEach((d,i)=>setTimeout(()=>i<3?setPh(i+1):onDone(),d)); },[]);
  return (
    <div style={{position:"fixed",inset:0,zIndex:9999}}>
      <PageBg src={BG.splash} overlay="rgba(3,10,5,.88)" style={{height:"100vh"}}>
        <div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",height:"100vh"}}>
          <div style={{width:114,height:114,borderRadius:32,position:"relative",marginBottom:24,
            transition:"all .85s cubic-bezier(.34,1.56,.64,1)",
            transform:ph>=1?"scale(1) rotate(0deg)":"scale(.1) rotate(-90deg)",opacity:ph>=1?1:0}}>
            <div style={{position:"absolute",inset:0,borderRadius:32,background:"linear-gradient(145deg,#059669,#064E3B)",boxShadow:"0 0 80px rgba(5,150,105,.6)"}}/>
            <div style={{position:"absolute",inset:3,borderRadius:29,background:"rgba(3,16,8,.5)",display:"flex",alignItems:"center",justifyContent:"center"}}>
              <span style={{fontSize:50}}>🌿</span>
            </div>
            {ph>=2&&<div style={{position:"absolute",inset:-12,borderRadius:44,border:"2px solid rgba(52,211,153,.4)",animation:"spin 8s linear infinite"}}/>}
            {ph>=2&&<div style={{position:"absolute",inset:-22,borderRadius:54,border:"1px solid rgba(52,211,153,.2)",animation:"spinR 13s linear infinite"}}/>}
          </div>
          <div style={{textAlign:"center",opacity:ph>=2?1:0,transform:ph>=2?"translateY(0)":"translateY(22px)",transition:"all .6s ease"}}>
            <div style={{fontFamily:"'Fraunces',serif",fontSize:52,fontWeight:900,color:"#fff",letterSpacing:4,lineHeight:1}}>VIMBISO</div>
            <div style={{fontSize:11,letterSpacing:9,color:"#34D399",marginTop:5}}>NETWORK</div>
          </div>
          <div style={{marginTop:12,opacity:ph>=3?1:0,transition:"all .5s ease",color:"rgba(255,255,255,.5)",fontSize:13,fontStyle:"italic"}}>
            Real-Time Informal Economy Operating System
          </div>
          <div style={{marginTop:50,opacity:ph>=2?1:0}}><WaveBars n={10} color="#34D399" h={30}/></div>
        </div>
      </PageBg>
    </div>
  );
};

// ── AUTH PAGE ─────────────────────────────────────────────────────────
const AuthPage = ({onAuth}) => {
  const [mode,setMode]=useState("land");
  const [f,setF]=useState({name:"",phone:"",pin:"",pin2:"",role:"buyer",loc:"",email:""});
  const [e,setE]=useState({});
  const [loading,setLoading]=useState(false);
  const [gUser,setGUser]=useState(null);
  const s=(k,v)=>setF(x=>({...x,[k]:v}));
  const clr=()=>setE({});
  const vPhone=p=>p.replace(/\D/g,"").length>=9?"":"Valid Zimbabwe number required";
  const vPin=p=>p.length>=4?"":"PIN must be 4–6 digits";
  const vName=n=>n.trim().length>=2?"":"Full name required";
  const vLoc=l=>l.trim().length>=2?"":"Location required";

  const login=()=>{
    const er={};
    if(vPhone(f.phone))er.phone=vPhone(f.phone);
    if(vPin(f.pin))er.pin=vPin(f.pin);
    if(Object.keys(er).length){setE(er);return;}
    setLoading(true);
    setTimeout(()=>{
      const u=DB.users.find(x=>x.phone===f.phone&&x.pin===f.pin);
      setLoading(false);
      if(!u){setE({pin:"Incorrect phone or PIN."});return;}
      onAuth(u);
    },900);
  };

  const signup=()=>{
    const er={};
    if(vName(f.name))er.name=vName(f.name);
    if(vPhone(f.phone))er.phone=vPhone(f.phone);
    if(vPin(f.pin))er.pin=vPin(f.pin);
    if(f.pin!==f.pin2)er.pin2="PINs do not match";
    if(vLoc(f.loc))er.loc=vLoc(f.loc);
    if(!f.role)er.role="Select a role";
    if(DB.users.find(u=>u.phone===f.phone))er.phone="Account with this phone exists.";
    if(Object.keys(er).length){setE(er);return;}
    setLoading(true);
    setTimeout(()=>{
      const nu={id:uid(),name:f.name,phone:f.phone,pin:f.pin,role:f.role,trust:50,location:f.loc,email:"",linked:null,auth:"phone"};
      DB.users.push(nu);
      DB.waitlist.push({id:uid(),name:f.name,phone:f.phone,role:f.role,ts:Date.now()});
      setLoading(false); onAuth(nu);
    },900);
  };

  const googleSignIn=()=>{
    setLoading(true);
    setTimeout(()=>{setLoading(false);setGUser({gid:"G-"+uid(),email:"user@gmail.com"});setMode("gfall");},1100);
  };

  const gFallback=()=>{
    const er={};
    if(vName(f.name))er.name=vName(f.name);
    if(vLoc(f.loc))er.loc=vLoc(f.loc);
    if(!f.role)er.role="Select a role";
    if(Object.keys(er).length){setE(er);return;}
    setLoading(true);
    setTimeout(()=>{
      const nu={id:uid(),name:f.name,phone:"",pin:"",role:f.role,trust:50,location:f.loc,email:gUser.email,linked:null,auth:"google",googleId:gUser.gid};
      DB.users.push(nu); setLoading(false); onAuth(nu);
    },700);
  };

  const linkAcc=()=>{
    const er={};
    if(vPhone(f.phone))er.phone=vPhone(f.phone);
    if(vPin(f.pin))er.pin=vPin(f.pin);
    if(Object.keys(er).length){setE(er);return;}
    setLoading(true);
    setTimeout(()=>{
      const ex=DB.users.find(u=>u.phone===f.phone&&u.pin===f.pin);
      if(!ex){setE({pin:"No account found."});setLoading(false);return;}
      ex.linked=gUser?.gid||"linked"; ex.email=gUser?.email; ex.auth="linked";
      setLoading(false); onAuth(ex);
    },900);
  };

  const roles=[{k:"buyer",e:"🛍",l:"Buyer"},{k:"vendor",e:"🏪",l:"Vendor"},{k:"farmer",e:"🌾",l:"Farmer"},{k:"delivery",e:"🛵",l:"Delivery"},{k:"agent",e:"🤝",l:"Agent"}];

  const Inp=({lbl,ph,value,onChange,type="text",max,icon,error})=>(
    <div style={{marginBottom:14}}>
      <label style={{fontSize:10,fontWeight:700,letterSpacing:1.5,color:"#475569",display:"block",marginBottom:5}}>{lbl}</label>
      <div style={{position:"relative"}}>
        {icon&&<span style={{position:"absolute",left:13,top:"50%",transform:"translateY(-50%)",fontSize:16,pointerEvents:"none"}}>{icon}</span>}
        <input
          type={type}
          placeholder={ph}
          maxLength={max}
          value={value}
          onChange={onChange}
          autoComplete="off"
          autoCorrect="off"
          autoCapitalize="off"
          spellCheck={false}
          style={{
            width:"100%",
            border:`1.5px solid ${error?"#EF4444":"#E2E8F0"}`,
            borderRadius:12,
            padding:`12px 14px 12px ${icon?"42px":"14px"}`,
            fontSize:16,
            outline:"none",
            background:error?"#FEF2F2":"#fff",
            color:"#0F172A",
            fontFamily:"'Cabinet Grotesk',sans-serif",
            WebkitAppearance:"none",
            appearance:"none",
            touchAction:"manipulation",
          }}
        />
      </div>
      {error&&<div style={{color:"#EF4444",fontSize:11,marginTop:4}}>⚠ {error}</div>}
    </div>
  )

  const AuthWrap=({children,title,sub,bgSrc,back})=>(
    <div style={{height:"100vh",display:"flex",flexDirection:"column",overflow:"hidden"}}>
      <PageBg src={bgSrc||BG.auth} overlay="rgba(2,6,4,.86)" style={{flexShrink:0,position:"relative"}}>
        <div style={{padding:"26px 20px 22px"}}>
          {back&&<button onClick={()=>{setMode(back);clr();}} style={{background:"rgba(255,255,255,.12)",border:"1px solid rgba(255,255,255,.22)",borderRadius:10,padding:"6px 12px",color:"#fff",fontSize:12,cursor:"pointer",marginBottom:12}}>← Back</button>}
          <div style={{fontFamily:"'Fraunces',serif",fontSize:26,fontWeight:700,color:"#fff"}}>{title}</div>
          {sub&&<div style={{color:"rgba(255,255,255,.65)",fontSize:12,marginTop:4}}>{sub}</div>}
          <div style={{position:"absolute",right:20,bottom:14,opacity:.4}}><WaveBars n={7} color="#fff" h={22}/></div>
        </div>
      </PageBg>
      <div style={{flex:1,overflowY:"auto",padding:"20px 20px 30px",background:"#F8FAFC"}}>{children}</div>
    </div>
  );

  if(mode==="land") return (
    <div style={{height:"100vh",overflow:"hidden"}}>
      <PageBg src={IMG_NFC} overlay="rgba(2,8,4,.87)" style={{height:"100vh",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:24}}>
        <div style={{position:"relative",zIndex:3,width:"100%",maxWidth:380,textAlign:"center"}}>
          <div style={{width:82,height:82,borderRadius:24,background:"linear-gradient(145deg,#059669,#064E3B)",display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 20px",boxShadow:"0 0 60px rgba(5,150,105,.5)",fontSize:40}}>🌿</div>
          <div style={{fontFamily:"'Fraunces',serif",fontSize:46,fontWeight:900,color:"#fff",letterSpacing:2,lineHeight:1}}>VIMBISO</div>
          <div style={{fontSize:11,letterSpacing:8,color:"#34D399",marginTop:5}}>NETWORK</div>
          <div style={{color:"rgba(255,255,255,.6)",fontSize:13,marginTop:12,marginBottom:40,lineHeight:1.5}}>Zimbabwe's Real-Time Informal Economy OS</div>
          <div style={{display:"flex",flexDirection:"column",gap:10}}>
            <button onClick={googleSignIn} style={{width:"100%",padding:15,borderRadius:14,background:"#fff",border:"none",cursor:"pointer",fontWeight:700,fontSize:14,color:"#0F172A",display:"flex",alignItems:"center",justifyContent:"center",gap:10,boxShadow:"0 4px 20px rgba(0,0,0,.3)"}}>
              <span style={{fontSize:20}}>🔵</span> Continue with Google
            </button>
            <button onClick={()=>{clr();setMode("login");}} style={{width:"100%",padding:15,borderRadius:14,background:"linear-gradient(135deg,#0F4C75,#1B9AAA)",border:"none",cursor:"pointer",fontWeight:800,fontSize:14,color:"#fff",boxShadow:"0 6px 24px rgba(15,76,117,.5)"}}>
              📱 Phone + PIN Login
            </button>
            <button onClick={()=>{clr();setMode("signup");}} style={{width:"100%",padding:15,borderRadius:14,background:"rgba(255,255,255,.12)",border:"1px solid rgba(255,255,255,.22)",cursor:"pointer",fontWeight:700,fontSize:14,color:"#fff"}}>
              ➕ Create New Account
            </button>
          </div>
          <div style={{marginTop:16,color:"rgba(255,255,255,.35)",fontSize:11}}>By continuing you agree to our Terms of Service</div>
          <div style={{marginTop:10,background:"rgba(255,255,255,.08)",borderRadius:10,padding:"8px 12px",fontSize:11,color:"rgba(255,255,255,.5)"}}>
            Demo login: +263771234561 to +263771234566 · PIN 1234
          </div>
        </div>
      </PageBg>
    </div>
  );

  if(mode==="login") return (
    <AuthWrap title="Welcome back" sub="Sign in with phone and PIN" bgSrc={IMG_MOBILE} back="land">
      <div style={{background:"#ECFDF5",borderRadius:12,padding:"10px 14px",marginBottom:16,fontSize:12,color:"#065F46",border:"1px solid #A7F3D0"}}>
        💡 Demo — Phone ends in 1-6 · PIN <strong>1234</strong><br/>
        <small>1=buyer 2=vendor 3=farmer 4=delivery 5=agent 6=admin</small>
      </div>
      <Inp lbl="PHONE" ph="+263 7X XXX XXXX" icon="📱" value={f.phone} onChange={e=>s('phone',e.target.value)}/>
      <Inp lbl="PIN" ph="Your secret PIN" type="password" max={6} icon="🔒" value={f.pin} onChange={e=>s('pin',e.target.value)}/>
      {e.pin?.includes("Incorrect")&&<div style={{background:"#FEE2E2",borderRadius:10,padding:"10px 14px",marginBottom:14,fontSize:12,color:"#991B1B"}}>⚠ {e.pin}</div>}
      <button onClick={login} disabled={loading} style={{width:"100%",padding:15,borderRadius:14,background:"linear-gradient(135deg,#0F4C75,#1B9AAA)",color:"#fff",fontWeight:800,fontSize:15,border:"none",cursor:"pointer"}}>{loading?"Logging in…":"LOGIN →"}</button>
      <div style={{textAlign:"center",marginTop:14,fontSize:13,color:"#64748B"}}>No account? <span onClick={()=>{clr();setMode("signup");}} style={{color:"#0F4C75",fontWeight:700,cursor:"pointer"}}>Sign Up</span></div>
    </AuthWrap>
  );

  if(mode==="signup") return (
    <AuthWrap title="Create Account" sub="Join the Vimbiso Network" bgSrc={IMG_COINS} back="land">
      <Inp lbl="FULL NAME" ph="Your full name" icon="👤" value={f.name} onChange={e=>s('name',e.target.value)}/>
      <Inp lbl="PHONE" ph="+263 7X XXX XXXX" icon="📱" value={f.phone} onChange={e=>s('phone',e.target.value)}/>
      <Inp lbl="LOCATION" ph="e.g. Mbare, Harare" icon="📍" value={f.loc} onChange={e=>s('loc',e.target.value)}/>
      <Inp lbl="PIN (4–6 digits)" ph="Create a PIN" type="password" max={6} icon="🔒" value={f.pin} onChange={e=>s('pin',e.target.value)}/>
      <Inp lbl="CONFIRM PIN" ph="Repeat PIN" type="password" max={6} icon="🔒" value={f.pin2} onChange={e=>s('pin2',e.target.value)}/>
      <div style={{marginBottom:14}}>
        <label style={{fontSize:10,fontWeight:700,letterSpacing:1.5,color:"#475569",display:"block",marginBottom:8}}>YOUR ROLE</label>
        <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8}}>
          {roles.map(r=>(<button key={r.k} onClick={()=>s("role",r.k)} style={{padding:"12px 6px",borderRadius:14,border:`2px solid ${f.role===r.k?"#0F4C75":"#E2E8F0"}`,background:f.role===r.k?"#EFF6FF":"#fff",cursor:"pointer",textAlign:"center"}}>
            <div style={{fontSize:22,marginBottom:3}}>{r.e}</div>
            <div style={{fontSize:11,fontWeight:700,color:f.role===r.k?"#0F4C75":"#374151"}}>{r.l}</div>
          </button>))}
        </div>
        {e.role&&<div style={{color:"#EF4444",fontSize:11,marginTop:4}}>⚠ {e.role}</div>}
      </div>
      <button onClick={signup} disabled={loading} style={{width:"100%",padding:15,borderRadius:14,background:"linear-gradient(135deg,#0F4C75,#1B9AAA)",color:"#fff",fontWeight:800,fontSize:15,border:"none",cursor:"pointer"}}>{loading?"Creating…":"CREATE ACCOUNT →"}</button>
      <div style={{textAlign:"center",marginTop:14,fontSize:13,color:"#64748B"}}>Have one? <span onClick={()=>{clr();setMode("login");}} style={{color:"#0F4C75",fontWeight:700,cursor:"pointer"}}>Log In</span></div>
    </AuthWrap>
  );

  if(mode==="gfall") return (
    <AuthWrap title="One more step" sub="Google needs a few more details" bgSrc={IMG_NFC}>
      <div style={{background:"#FEF3C7",borderRadius:12,padding:"10px 14px",marginBottom:14,fontSize:12,color:"#92400E",border:"1px solid #FCD34D"}}>ℹ Complete missing fields below.</div>
      <Inp lbl="YOUR NAME" ph="Full name" icon="👤" value={f.name} onChange={e=>s('name',e.target.value)}/>
      <Inp lbl="LOCATION" ph="e.g. Mbare, Harare" icon="📍" value={f.loc} onChange={e=>s('loc',e.target.value)}/>
      <div style={{marginBottom:14}}>
        <label style={{fontSize:10,fontWeight:700,letterSpacing:1.5,color:"#475569",display:"block",marginBottom:8}}>YOUR ROLE</label>
        <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8}}>
          {roles.map(r=>(<button key={r.k} onClick={()=>s("role",r.k)} style={{padding:"11px 6px",borderRadius:14,border:`2px solid ${f.role===r.k?"#0F4C75":"#E2E8F0"}`,background:f.role===r.k?"#EFF6FF":"#fff",cursor:"pointer",textAlign:"center"}}><div style={{fontSize:20,marginBottom:2}}>{r.e}</div><div style={{fontSize:11,fontWeight:700,color:f.role===r.k?"#0F4C75":"#374151"}}>{r.l}</div></button>))}
        </div>
        {e.role&&<div style={{color:"#EF4444",fontSize:11,marginTop:4}}>⚠ {e.role}</div>}
      </div>
      <button onClick={gFallback} disabled={loading} style={{width:"100%",padding:15,borderRadius:14,background:"linear-gradient(135deg,#0F4C75,#1B9AAA)",color:"#fff",fontWeight:800,fontSize:15,border:"none",cursor:"pointer",marginBottom:10}}>{loading?"Saving…":"COMPLETE PROFILE →"}</button>
      <button onClick={()=>setMode("link")} style={{width:"100%",padding:13,borderRadius:14,background:"#F0F9FF",border:"1px solid #BAE6FD",color:"#0369A1",fontWeight:700,cursor:"pointer",fontSize:13}}>🔗 Link to Existing Phone+PIN Account</button>
    </AuthWrap>
  );

  if(mode==="link") return (
    <AuthWrap title="Link Accounts" sub="Merge Google + Phone without duplicates" bgSrc={IMG_COINS} back="gfall">
      <div style={{background:"#ECFDF5",borderRadius:12,padding:"10px 14px",marginBottom:14,fontSize:12,color:"#065F46",border:"1px solid #A7F3D0"}}>🔗 Linking <strong>{gUser?.email}</strong> to existing profile.</div>
      <Inp lbl="YOUR PHONE" ph="+263 7X XXX XXXX" icon="📱" value={f.phone} onChange={e=>s('phone',e.target.value)}/>
      <Inp lbl="YOUR PIN" ph="Existing PIN" type="password" max={6} icon="🔒" value={f.pin} onChange={e=>s('pin',e.target.value)}/>
      {e.pin&&<div style={{background:"#FEE2E2",borderRadius:10,padding:"10px 14px",marginBottom:14,fontSize:12,color:"#991B1B"}}>⚠ {e.pin}</div>}
      <button onClick={linkAcc} disabled={loading} style={{width:"100%",padding:15,borderRadius:14,background:"linear-gradient(135deg,#0F4C75,#1B9AAA)",color:"#fff",fontWeight:800,fontSize:15,border:"none",cursor:"pointer"}}>{loading?"Linking…":"LINK & CONTINUE →"}</button>
    </AuthWrap>
  );
  return null;
};


