// Helper: every tab gets a fixed bg image + scrollable content on top
const TabWrap = ({bg, overlay="rgba(4,10,6,.80)", dark=false, children}) => (
  <div style={{flex:1,overflowY:"auto",position:"relative"}}>
    <div style={{position:"fixed",inset:0,backgroundImage:`url(${bg})`,backgroundSize:"cover",backgroundPosition:"center",filter:"brightness(.28)",zIndex:0,animation:"bgKen 20s ease infinite alternate"}}/>
    <div style={{position:"relative",zIndex:1}}>{children}</div>
  </div>
);

